import json
for r in ["20261010T103641Z-f6fc324", "20261010T120139Z-5c3370f"]:
    d = json.load(open("runs/" + r + "/result.json"))
    print(r, list(d.keys()))
    for k, v in d.items():
        if k not in ("agent", "verifier"):
            print(" ", k, str(v)[:150])
    for who in ("agent", "verifier"):
        a = d.get(who, {})
        print(" ", who, {k: str(v)[:100] for k, v in a.items() if k not in ("steps", "attempts")})
        for s in a.get("steps", []):
            print("    step", {k: str(v)[:110] for k, v in s.items() if k != "output_tail"}, len(s.get("output_tail", [])))
        for t in a.get("attempts", []):
            print("    att", {k: str(v)[:80] for k, v in t.items()})
    print(open("runs/" + r + "/fix.patch").read()[:700])
